"""RFC 6902 patch generation helpers for jd-compatible output."""
import json


def _ptr(path):
    return ''.join('/' + str(x).replace('~', '~0').replace('/', '~1') for x in path)


def _equal(a, b):
    # JSON booleans are distinct from numbers even though Python bool subclasses int.
    if isinstance(a, bool) or isinstance(b, bool):
        return type(a) is type(b) and a == b
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    return a == b


def _lcs_edits(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if _equal(a[i - 1], b[j - 1]):
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    matches = []
    i, j = n, m
    while i and j:
        if _equal(a[i - 1], b[j - 1]):
            matches.append((i - 1, j - 1))
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    matches.reverse()
    edits, oldpos, newpos = [], 0, 0
    for oi, ni in matches + [(n, m)]:
        if oldpos < oi or newpos < ni:
            edits.append((oldpos, oi, newpos, ni))
        oldpos, newpos = oi + 1, ni + 1
    return edits


def generate_patch(before, after):
    """Return operations generated by jd's -f patch mode.

    Changed scalar values use a guarded remove/add pair. Object changes recurse,
    while arrays are conservatively replaced at changed indices.
    """
    ops = []

    def emit(op, path, value=None, include=True):
        d = {'op': op, 'path': _ptr(path)}
        if include:
            d['value'] = value
        ops.append(d)

    def walk(a, b, path):
        if _equal(a, b):
            return
        if isinstance(a, dict) and isinstance(b, dict):
            # Preserve source insertion order, followed by target insertion order.
            for k in a:
                if k not in b:
                    emit('test', path + [k], a[k])
                    emit('remove', path + [k], a[k])
            for k in b:
                if k not in a:
                    emit('add', path + [k], b[k])
                else:
                    walk(a[k], b[k], path + [k])
            return
        if isinstance(a, list) and isinstance(b, list):
            if a and b and all(isinstance(item, dict) for item in a + b):
                shared = min(len(a), len(b))
                for index in range(shared):
                    walk(a[index], b[index], path + [index])
                if len(a) > shared:
                    if shared:
                        emit('test', path + [shared - 1], b[shared - 1])
                    for item in a[shared:]:
                        emit('test', path + [shared], item)
                        emit('remove', path + [shared], item)
                elif len(b) > shared:
                    if shared:
                        emit('test', path + [shared - 1], b[shared - 1])
                    for item in reversed(b[shared:]):
                        emit('add', path + [shared], item)
                return
            # Translate minimal list hunks, guarding one unchanged neighbor
            # on either side and each removed value.
            offset = 0
            for x1, x2, y1, y2 in _lcs_edits(a, b):
                start, end = max(0, x1 - 1), min(len(a), x2 + 1)
                guarded = set(range(start, x1)) | set(range(x2, end))
                for index in sorted(guarded):
                    emit('test', path + [index + offset], a[index])
                for index in range(x1, x2):
                    current_index = x1 + offset
                    emit('test', path + [current_index], a[index])
                    emit('remove', path + [current_index], a[index])
                for index in range(y2 - 1, y1 - 1, -1):
                    emit('add', path + [x1 + offset], b[index])
                offset += (y2 - y1) - (x2 - x1)
            return
        emit('test', path, a)
        emit('remove', path, a)
        emit('add', path, b)

    walk(before, after, [])
    return ops


def render_patch(before, after):
    def normalize(value):
        if isinstance(value, float) and value.is_integer() and abs(value) < 1e21:
            return int(value)
        if isinstance(value, list):
            return [normalize(item) for item in value]
        if isinstance(value, dict):
            return {key: normalize(item) for key, item in value.items()}
        return value
    return json.dumps(normalize(generate_patch(before, after)), ensure_ascii=False,
                      separators=(',', ':'), sort_keys=True)
